
from stages_12 import T

NOTE = "Framework APIs change between versions; check the linked official docs for the version you install."

STAGE3 = [
T("LangChain",
  "LangChain is an open-source framework (Python and JavaScript) that provides standard building blocks for LLM applications: chat model wrappers for many providers, prompt templates, output parsers, tools, retrievers, document loaders and agents.",
  "It lets you swap providers with one line, reuse hundreds of integrations (vector stores, loaders, tools) and build RAG and agents faster. Many customer codebases already use it, so FDEs must read and debug it.",
  ["Chat models: ChatAnthropic, ChatOpenAI, ChatGoogleGenerativeAI share one interface (.invoke, .stream, .batch).",
   "Prompt templates insert variables into messages.",
   "Runnables chain steps with the | operator (prompt | model | parser).",
   "Tools are Python functions decorated with @tool; models call them through bind_tools.",
   "Retrievers return relevant documents from vector stores for RAG.",
   "LangChain's agent features are built on LangGraph; LangSmith provides tracing and evaluation. " + NOTE],
  ["pip install langchain langchain-anthropic (or langchain-openai).",
   "Create a chat model and call .invoke with a question.",
   "Build a prompt | model | parser chain for structured extraction.",
   "Define a tool with @tool and bind it to the model.",
   "Turn on tracing in LangSmith to see each step."],
  "# pip install langchain langchain-anthropic\nfrom langchain_anthropic import ChatAnthropic\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom langchain_core.output_parsers import StrOutputParser\nfrom langchain_core.tools import tool\n\nllm = ChatAnthropic(model='claude-opus-5-5', max_tokens=1500)\n\nprompt = ChatPromptTemplate.from_messages([\n    ('system', 'You summarise property listings for buyers in {n} bullet points.'),\n    ('human', '{listing}'),\n])\nchain = prompt | llm | StrOutputParser()\nprint(chain.invoke({'n': 3, 'listing': '3BHK, 1650 sq ft, 12th floor, east facing, 2 parking, near metro'}))\n\n@tool\ndef emi(principal: float, annual_rate: float, years: int) -> float:\n    \"\"\"Monthly EMI for a home loan.\"\"\"\n    r, n = annual_rate / 12 / 100, years * 12\n    return round(principal * r * (1 + r) ** n / ((1 + r) ** n - 1), 2)\n\nreply = llm.bind_tools([emi]).invoke('EMI on 60 lakh at 8.5% for 20 years?')\nprint(reply.tool_calls)  # the model asks to call emi(...); your code runs it",
  ["Using deep abstractions you cannot debug; trace every step.",
   "Copying tutorial code written for an older LangChain version.",
   "Adding LangChain when a direct SDK call would be simpler."],
  [("When would you use LangChain instead of the provider SDK directly?", "When you need many integrations (loaders, vector stores, multiple providers) or want to switch providers easily; for a simple single-provider call, the SDK is simpler and easier to debug."),
   ("What is a Runnable/chain?", "A composable step with a standard interface (invoke, stream, batch); chaining them with | passes each output into the next step.")],
  "Build a LangChain RAG chain over 10 PDFs with a retriever and citations, and inspect a trace in LangSmith.",
  [("LangChain docs (official)", "https://docs.langchain.com/oss/python/langchain/overview"), ("LangChain Anthropic integration", "https://docs.langchain.com/oss/python/integrations/chat/anthropic"), ("LangSmith docs", "https://docs.langchain.com/langsmith/home")]),

T("LangGraph",
  "LangGraph is a library for building stateful, controllable agents and workflows as graphs: nodes are steps (functions or model calls), edges decide what runs next, and a shared state object carries data between them. It supports persistence (checkpoints), streaming and human-in-the-loop pauses.",
  "Enterprise agents need predictable control flow, retries, approvals and the ability to resume after failures. LangGraph makes the flow explicit, which is easier to test, debug and explain to customers than a free-running agent.",
  ["State: a typed dictionary that every node reads and updates.",
   "Nodes: Python functions that take state and return updates.",
   "Edges: fixed (A → B) or conditional (a router function chooses the next node).",
   "START and END mark entry and exit.",
   "Checkpointers save state after each step so a run can pause (for approval) and resume.",
   "Cycles allow agent loops (model → tool → model) with limits. " + NOTE],
  ["pip install langgraph langchain-anthropic.",
   "Define the state (TypedDict) for a lead-triage workflow.",
   "Write nodes: classify, enrich, route_hot, route_cold.",
   "Add a conditional edge after classify.",
   "Compile and invoke with a sample lead; print the final state.",
   "Add a checkpointer and an interrupt before sending any message to the customer."],
  "# pip install langgraph langchain-anthropic\nfrom typing import TypedDict\nfrom langgraph.graph import StateGraph, START, END\nfrom langchain_anthropic import ChatAnthropic\n\nllm = ChatAnthropic(model='claude-opus-5-5', max_tokens=500)\n\nclass Lead(TypedDict, total=False):\n    message: str\n    intent: str\n    action: str\n\ndef classify(state: Lead) -> Lead:\n    out = llm.invoke(f\"Reply with one word, buy, rent or other: {state['message']}\").content\n    return {'intent': out.strip().lower()}\n\ndef hot(state: Lead) -> Lead:\n    return {'action': 'Assign to senior agent and call within 5 minutes'}\n\ndef nurture(state: Lead) -> Lead:\n    return {'action': 'Add to weekly email nurture'}\n\ndef route(state: Lead) -> str:\n    return 'hot' if state['intent'] in ('buy', 'rent') else 'nurture'\n\ng = StateGraph(Lead)\ng.add_node('classify', classify)\ng.add_node('hot', hot)\ng.add_node('nurture', nurture)\ng.add_edge(START, 'classify')\ng.add_conditional_edges('classify', route, {'hot': 'hot', 'nurture': 'nurture'})\ng.add_edge('hot', END)\ng.add_edge('nurture', END)\napp = g.compile()\nprint(app.invoke({'message': 'Want to buy a 2BHK in Pune this month'}))",
  ["Putting everything in one giant node.",
   "Unbounded cycles with no step limit.",
   "Storing large documents in state instead of references.",
   "No checkpointer, so long runs cannot resume or pause for approval."],
  [("Why model an agent as a graph?", "Explicit steps and routing make behaviour predictable, testable and auditable; you can add approvals, retries and persistence at specific points instead of trusting a free-form loop."),
   ("How does human-in-the-loop work in LangGraph?", "With a checkpointer, the graph can interrupt before or inside a node, save state, wait for human input, then resume from the saved state with the human's decision.")],
  "Build a LangGraph claims workflow: extract fields, validate, auto-approve small claims, and interrupt for human approval above a threshold.",
  [("LangGraph docs (official)", "https://docs.langchain.com/oss/python/langgraph/overview"), ("LangGraph: interrupts (human-in-the-loop)", "https://docs.langchain.com/oss/python/langgraph/interrupts"), ("LangChain Academy (free courses)", "https://academy.langchain.com/")]),

T("CrewAI",
  "CrewAI is an open-source Python framework for multi-agent systems where each agent has a role, goal and backstory, works on tasks with expected outputs, and agents collaborate as a 'crew' run sequentially or hierarchically. Flows add event-driven, stateful control.",
  "It is a fast way to prototype role-based teams (researcher, analyst, writer) and is popular with automation agencies. FDEs should know when its simplicity helps and when a controlled graph is better.",
  ["Agent: role, goal, backstory, tools and the LLM it uses.",
   "Task: description, expected_output and the agent responsible.",
   "Crew: the list of agents and tasks plus a process (sequential or hierarchical with a manager).",
   "Tools: built-in (search, scraping, file reading) or custom Python functions.",
   "kickoff() runs the crew and returns the final output; outputs of earlier tasks feed later ones.",
   "Flows chain crews and plain code with state and conditions. " + NOTE],
  ["pip install crewai.",
   "Set ANTHROPIC_API_KEY (or another provider key).",
   "Define a market researcher and a report writer agent.",
   "Define two tasks with clear expected outputs.",
   "Create the crew, run kickoff with inputs, and review the result.",
   "Add a custom tool and limit iterations."],
  "# pip install crewai\nfrom crewai import Agent, Task, Crew, Process\n\nLLM = 'anthropic/claude-opus-5-5'  # provider/model string\n\nresearcher = Agent(\n    role='Real-estate market researcher',\n    goal='Summarise demand drivers for {area}',\n    backstory='You analyse housing markets in Indian cities and cite assumptions.',\n    llm=LLM, max_iter=5,\n)\nwriter = Agent(\n    role='Client report writer',\n    goal='Write a one-page buyer brief',\n    backstory='You write clear, jargon-free briefs for first-time buyers.',\n    llm=LLM,\n)\nresearch = Task(description='List 5 demand drivers and 3 risks for buying in {area}.',\n                expected_output='Two bullet lists with one-line explanations', agent=researcher)\nbrief = Task(description='Turn the research into a buyer brief with a recommendation.',\n             expected_output='A 300-word brief with headings', agent=writer)\n\ncrew = Crew(agents=[researcher, writer], tasks=[research, brief], process=Process.sequential)\nprint(crew.kickoff(inputs={'area': 'Whitefield, Bengaluru'}))",
  ["Too many agents for a simple task, multiplying cost and errors.",
   "Vague expected outputs, so agents drift.",
   "No iteration limits or cost monitoring.",
   "Presenting generated research as fact without sources."],
  [("CrewAI vs LangGraph?", "CrewAI is quicker for role-based collaboration with less code; LangGraph gives explicit, fine-grained control over state, routing, persistence and approvals, which suits complex production workflows."),
   ("How do you keep a multi-agent crew reliable?", "Clear roles and expected outputs, few agents, tool restrictions, iteration limits, evaluation of final outputs and logging every step.")],
  "Build a two-agent crew that turns a customer's meeting notes into a requirements document and a risk list, then evaluate the outputs against a checklist.",
  [("CrewAI docs (official)", "https://docs.crewai.com/"), ("CrewAI GitHub", "https://github.com/crewAIInc/crewAI")]),

T("Tool calling",
  "Tool calling (function calling) lets a model request that your code run a named function with structured arguments. The model decides when a tool is needed; your application executes it and returns the result; the model then continues.",
  "Tools turn a model from a text generator into a system that can look up orders, query databases, create tickets and send messages. Almost every enterprise agent is built on tool calling, so safe, well-designed tools are central to FDE work.",
  ["Define each tool: a clear name, a description of when to use it, and a JSON schema for its inputs.",
   "Send the tools with the request. If a tool is needed, the model returns a tool call (stop_reason tool_use for Claude) instead of a final answer.",
   "Your code validates the arguments, checks permissions, runs the function and returns the result (or an error) referencing the call ID.",
   "The model reads the result and either calls another tool or answers.",
   "Strict schemas (strict: true on Claude tools) guarantee arguments match the schema.",
   "Side-effecting tools (payments, emails, deletes) need confirmation and audit logs."],
  ["Write the business function (get_order_status).",
   "Describe it as a tool with a schema.",
   "Implement the loop: call model → run tools → return results → repeat until end_turn.",
   "Add argument validation and a maximum number of loop iterations.",
   "Log every tool call with inputs, outputs and timing."],
  "import anthropic, json\nclient = anthropic.Anthropic()\n\nORDERS = {'A100': 'Shipped, arrives Friday', 'A101': 'Payment pending'}\n\ndef get_order_status(order_id: str) -> str:\n    return ORDERS.get(order_id, 'Order not found')\n\ntools = [{\n    'name': 'get_order_status',\n    'description': 'Look up the delivery status of a customer order by its ID, e.g. A100.',\n    'input_schema': {'type': 'object',\n                     'properties': {'order_id': {'type': 'string', 'pattern': '^A[0-9]{3}$'}},\n                     'required': ['order_id'], 'additionalProperties': False},\n    'strict': True,\n}]\nmessages = [{'role': 'user', 'content': 'Where is my order A100?'}]\n\nfor _ in range(5):  # safety limit on loop iterations\n    resp = client.messages.create(model='claude-opus-5-5', max_tokens=2000, tools=tools, messages=messages)\n    if resp.stop_reason != 'tool_use':\n        print(''.join(b.text for b in resp.content if b.type == 'text'))\n        break\n    messages.append({'role': 'assistant', 'content': resp.content})\n    results = []\n    for block in resp.content:\n        if block.type == 'tool_use' and block.name == 'get_order_status':\n            out = get_order_status(**block.input)\n            results.append({'type': 'tool_result', 'tool_use_id': block.id, 'content': out})\n    messages.append({'role': 'user', 'content': results})  # all results in one message",
  ["Vague tool descriptions, so the model calls the wrong tool.",
   "Executing tool arguments as raw SQL or shell commands.",
   "No loop limit, so the agent can run forever.",
   "Dropping failed tool results instead of returning them with is_error."],
  [("How do you make tool use safe?", "Least-privilege tools, strict schemas and argument validation, user-scoped data access, confirmation for side effects, loop and cost limits, and audit logs of every call."),
   ("What makes a good tool definition?", "A specific name, a description saying what it does and when to use it, a tight schema with required fields and allowed values, and concise, structured results.")],
  "Give an assistant three tools (search_properties, book_visit, get_lead) and make book_visit require explicit user confirmation before execution.",
  [("Claude: tool use overview", "https://docs.claude.com/en/docs/agents-and-tools/tool-use/overview"), ("OpenAI: function calling", "https://platform.openai.com/docs/guides/function-calling"), ("Gemini: function calling", "https://ai.google.dev/gemini-api/docs/function-calling")]),

T("MCP (Model Context Protocol)",
  "MCP is an open protocol that standardises how AI applications connect to tools and data. An MCP server exposes tools, resources and prompts; any MCP-compatible host (Claude Desktop, Claude Code, IDEs, agent frameworks) can connect to it through an MCP client.",
  "Instead of building a separate integration for every AI app, a company builds one MCP server for each system (CRM, ticketing, database) and reuses it everywhere, with consistent permissions. FDEs increasingly deliver MCP servers to customers.",
  ["Host: the AI application. Client: the connector the host creates for each server. Server: your program exposing capabilities.",
   "Primitives: tools (actions the model can call), resources (data the app can read), prompts (reusable templates).",
   "Messages use JSON-RPC 2.0.",
   "Transports: STDIO for local servers launched by the host; Streamable HTTP for remote servers.",
   "Remote servers use OAuth-based authorisation; hosts ask users before running sensitive tools.",
   "The specification is versioned; check which version your SDK and hosts support."],
  ["pip install mcp (official Python SDK).",
   "Create a server with FastMCP and add two tools and one resource.",
   "Run it locally and test with the MCP Inspector (npx @modelcontextprotocol/inspector).",
   "Register it in Claude Desktop or Claude Code configuration.",
   "Ask the assistant a question that needs your tool and watch the call.",
   "Add input validation, authentication for remote use, and logging."],
  "# pip install mcp\nfrom mcp.server.fastmcp import FastMCP\n\nmcp = FastMCP('property-crm')\n\nLISTINGS = [\n    {'id': 'P1', 'area': 'Whitefield', 'bhk': 2, 'price_lakh': 85},\n    {'id': 'P2', 'area': 'Whitefield', 'bhk': 3, 'price_lakh': 140},\n    {'id': 'P3', 'area': 'HSR Layout', 'bhk': 2, 'price_lakh': 120},\n]\n\n@mcp.tool()\ndef search_listings(area: str, max_price_lakh: float, bhk: int | None = None) -> list[dict]:\n    \"\"\"Find listings in an area under a budget, optionally filtered by BHK.\"\"\"\n    return [l for l in LISTINGS if l['area'].lower() == area.lower()\n            and l['price_lakh'] <= max_price_lakh and (bhk is None or l['bhk'] == bhk)]\n\n@mcp.resource('listing://{listing_id}')\ndef get_listing(listing_id: str) -> str:\n    \"\"\"Full details of one listing.\"\"\"\n    return str(next((l for l in LISTINGS if l['id'] == listing_id), 'Not found'))\n\nif __name__ == '__main__':\n    mcp.run()  # STDIO transport by default",
  ["Installing MCP servers from unknown sources.",
   "Exposing write tools without confirmation or scopes.",
   "Returning huge payloads that flood the model's context.",
   "Ignoring the protocol version supported by the host."],
  [("What problem does MCP solve?", "It replaces many custom, app-specific integrations with one standard protocol, so a tool or data source built once works across many AI applications."),
   ("Tools vs resources vs prompts?", "Tools are actions the model decides to call; resources are data the application reads and supplies as context; prompts are reusable templates users or apps select."),
   ("How do you secure a remote MCP server?", "HTTPS, OAuth-based authorisation with scoped tokens, per-user permissions on data, input validation, rate limits, audit logs and user consent for sensitive tools.")],
  "Build an MCP server for a ticketing system (create_ticket, get_ticket, list_open) and connect it to Claude Desktop or Claude Code.",
  [("Model Context Protocol (official)", "https://modelcontextprotocol.io/"), ("MCP architecture specification", "https://modelcontextprotocol.io/specification/2025-11-25/architecture"), ("MCP Python SDK", "https://github.com/modelcontextprotocol/python-sdk")]),

T("Agent memory",
  "Agent memory is how an AI system keeps useful information beyond a single model call. Short-term memory is the state of the current task or conversation; long-term memory is facts, preferences and past outcomes stored outside the model and brought back when relevant.",
  "Models are stateless: each call only knows what you send. Without memory, assistants forget the customer's preferences, repeat questions and lose progress on long tasks; with too much memory, they get slow, costly and confused.",
  ["Short-term: the messages and state of the current run (conversation history, task state, tool results).",
   "Long-term semantic memory: facts about users or entities ('prefers 3BHK near metro').",
   "Episodic memory: records of past interactions and outcomes.",
   "Procedural memory: learned instructions or playbooks.",
   "Storage: databases, key-value stores, vector stores (for retrieval by meaning), or files (Claude's memory tool reads and writes files through your code).",
   "Write policy (what to save), read policy (what to retrieve), and privacy rules (consent, retention, deletion) are design decisions."],
  ["Decide what is worth remembering (stable preferences, decisions) and what is not (small talk, sensitive data).",
   "Create a memory table keyed by user with fact, source and timestamp.",
   "After each conversation, extract candidate facts with the model and save approved ones.",
   "Before each conversation, load the user's top relevant facts into the context.",
   "Provide a way for users to view and delete their memory."],
  "import sqlite3, time\ndb = sqlite3.connect('memory.db')\ndb.execute('CREATE TABLE IF NOT EXISTS memory (user_id TEXT, fact TEXT, created REAL)')\n\ndef remember(user_id: str, fact: str) -> None:\n    db.execute('INSERT INTO memory VALUES (?, ?, ?)', (user_id, fact, time.time()))\n    db.commit()\n\ndef recall(user_id: str, limit: int = 10) -> list[str]:\n    rows = db.execute('SELECT fact FROM memory WHERE user_id = ? ORDER BY created DESC LIMIT ?', (user_id, limit))\n    return [r[0] for r in rows]\n\ndef forget(user_id: str) -> None:            # honour deletion requests\n    db.execute('DELETE FROM memory WHERE user_id = ?', (user_id,))\n    db.commit()\n\nremember('u42', 'Looking for a 3BHK near a metro station, budget about 1.4 crore')\nprofile = '\\n'.join(recall('u42'))\nsystem = f'Known facts about this customer (may be outdated, confirm if important):\\n{profile}'",
  ["Saving everything, including sensitive data, without consent.",
   "Never expiring old facts, so the assistant acts on outdated preferences.",
   "Mixing users' memories through missing user IDs.",
   "Putting all memory in every prompt instead of retrieving relevant items."],
  [("Short-term vs long-term memory in agents?", "Short-term memory is the working context of the current task; long-term memory persists across sessions in external storage and is retrieved selectively."),
   ("What privacy issues does memory raise?", "Storing personal data needs consent, purpose limits, retention rules, access control and user rights to see and delete it, in line with laws such as GDPR and India's DPDP Act.")],
  "Add long-term memory to a property assistant: extract preferences after each chat, show them on a profile page, and let the user delete them.",
  [("Claude: memory tool", "https://docs.claude.com/en/docs/agents-and-tools/tool-use/memory-tool"), ("LangGraph: memory concepts", "https://docs.langchain.com/oss/python/langgraph/memory")]),

T("Multi-agent workflows",
  "A multi-agent workflow splits work among several model-driven agents or steps, each with a focused role, instructions and tools, coordinated by an orchestrator or a fixed sequence.",
  "Some tasks are too broad for one context window or benefit from specialisation and parallel work (researching many sources, processing many documents, drafting then reviewing). Done badly, multi-agent systems multiply cost and errors, so knowing when and how to use them matters.",
  ["Prompt chaining: fixed sequence where each step's output feeds the next (extract → validate → draft).",
   "Routing: a classifier sends each input to a specialised handler.",
   "Parallelisation: several workers handle independent parts at once, then results are combined.",
   "Orchestrator–workers: a lead model plans sub-tasks dynamically and delegates them.",
   "Evaluator–optimiser: one agent produces, another critiques, and the first revises.",
   "Shared state, clear hand-off formats, limits and final verification keep the system controlled."],
  ["Write the task as steps; check whether one agent with tools can do it (start simple).",
   "If not, choose a pattern (chain, route, parallel, orchestrator, evaluator).",
   "Define each agent's input, output format and tools.",
   "Implement the orchestration in plain code first; add a framework only if needed.",
   "Log each agent's input and output; evaluate the final result against a rubric."],
  "import anthropic, concurrent.futures as cf\nclient = anthropic.Anthropic()\n\ndef ask(system: str, prompt: str, model: str = 'claude-opus-5-5') -> str:\n    r = client.messages.create(model=model, max_tokens=2000, system=system,\n                               messages=[{'role': 'user', 'content': prompt}])\n    return ''.join(b.text for b in r.content if b.type == 'text')\n\nsections = ['Location and connectivity', 'Pricing trend', 'Builder track record', 'Legal checks']\nproperty_notes = open('property_notes.txt', encoding='utf-8').read()\n\n# Parallel workers (a cheaper model is fine for focused drafting)\nwith cf.ThreadPoolExecutor() as pool:\n    drafts = list(pool.map(lambda s: ask(f'You write the \"{s}\" section of a buyer report.', property_notes, 'claude-haiku-5-5'), sections))\n\n# Reviewer combines and checks\nreport = ask('You are an editor. Merge the sections, remove contradictions, and flag any claim not supported by the notes.',\n             '\\n\\n'.join(f'## {s}\\n{d}' for s, d in zip(sections, drafts)) + f'\\n\\n<notes>{property_notes}</notes>')\nprint(report)",
  ["Using many agents where one would do.",
   "Agents passing long unstructured text to each other.",
   "No final verification step.",
   "No overall cost or time limit."],
  [("When is a multi-agent design justified?", "When sub-tasks are independent and benefit from parallel work, need different tools or expertise, or exceed one context window; otherwise a single agent or simple chain is cheaper and more reliable."),
   ("How do you debug a multi-agent system?", "Trace each agent's inputs, outputs, tool calls and costs; test each agent alone with fixed inputs; then test the orchestration with recorded cases.")],
  "Build an orchestrator that splits a 50-page tender document into sections, has workers summarise requirements in parallel, and has a reviewer produce a compliance checklist.",
  [("Anthropic: building effective agents", "https://www.anthropic.com/engineering/building-effective-agents"), ("Anthropic: how we built our multi-agent research system", "https://www.anthropic.com/engineering/built-multi-agent-research-system"), ("OpenAI Agents SDK: handoffs", "https://openai.github.io/openai-agents-python/handoffs/")]),

T("Human-in-the-loop",
  "Human-in-the-loop (HITL) designs a system so that people review, approve, correct or take over at defined points: before risky actions, when confidence is low, or for a sample of outputs.",
  "Enterprises accept AI agents only when consequential actions (payments, customer emails, data changes, credit or medical decisions) stay under human control with an audit trail. HITL also produces corrected examples that improve the system.",
  ["Approval gates: the agent proposes an action and waits for a person to approve, edit or reject.",
   "Escalation: hand the case to a human when confidence is low, the request is out of scope or the customer asks.",
   "Review queues: people check outputs before release or sample them after.",
   "Thresholds: amount, risk category or model confidence decide which path a case takes.",
   "State must be saved while waiting (a checkpoint or database record) so the run can resume.",
   "Every decision is logged: who approved what, when, and with which information."],
  ["List every action the agent can take and rate its risk.",
   "Decide which actions need approval and the thresholds.",
   "Store proposed actions in a pending table with all context.",
   "Build a simple approval screen or Slack/Teams message with approve/reject.",
   "Execute only approved actions; log the decision and outcome.",
   "Review rejected proposals weekly to improve prompts and rules."],
  "import uuid, datetime\nPENDING: dict[str, dict] = {}   # use a database table in production\nAUDIT: list[dict] = []\n\ndef propose_refund(order_id: str, amount: float, reason: str) -> str:\n    if amount <= 500:                       # low risk: auto-approve\n        return execute_refund(order_id, amount, approver='auto')\n    pid = str(uuid.uuid4())\n    PENDING[pid] = {'order_id': order_id, 'amount': amount, 'reason': reason}\n    return f'Refund of {amount} sent for manager approval (request {pid})'\n\ndef decide(pid: str, approver: str, approve: bool) -> str:\n    req = PENDING.pop(pid)\n    AUDIT.append({**req, 'approver': approver, 'approved': approve, 'at': datetime.datetime.utcnow().isoformat()})\n    return execute_refund(req['order_id'], req['amount'], approver) if approve else 'Refund rejected'\n\ndef execute_refund(order_id: str, amount: float, approver: str) -> str:\n    # call the payment API here\n    return f'Refunded {amount} on {order_id} (approved by {approver})'",
  ["Approval screens that lack the information needed to decide.",
   "Too many approvals, so people click 'approve' without reading.",
   "No timeout or reminder for pending approvals.",
   "Not learning from rejected proposals."],
  [("Where would you put human checkpoints in an AI claims process?", "Before any payment above a threshold, for any denial, for low-confidence extractions, for cases flagged as unusual or potentially fraudulent, and for a random sample of auto-approved claims for quality control."),
   ("How do you avoid approval fatigue?", "Approve only risky actions, auto-handle low-risk ones, show concise evidence and the model's reasoning summary, batch similar items, and measure approval rates to tune thresholds.")],
  "Add an approval gate to an email-sending agent: drafts go to a review queue, and only approved drafts are sent, with a full audit log.",
  [("LangGraph: human-in-the-loop", "https://docs.langchain.com/oss/python/langgraph/interrupts"), ("Google PAIR: People + AI Guidebook", "https://pair.withgoogle.com/guidebook/"), ("NIST AI Risk Management Framework", "https://www.nist.gov/itl/ai-risk-management-framework")]),
]

STAGE4 = [
T("FastAPI",
  "FastAPI is a modern Python web framework for building APIs. It uses Python type hints and Pydantic models to validate requests and responses automatically, supports async code, and generates interactive API documentation at /docs.",
  "Most AI backends are Python services that expose model features as HTTP APIs to web apps, mobile apps and other systems. FastAPI is the most common choice for this because it is fast to write, fast to run and self-documenting.",
  ["Create an app with app = FastAPI() and add routes with decorators (@app.get, @app.post).",
   "Path parameters (/leads/{lead_id}) and query parameters (?limit=10) come from function arguments.",
   "Request bodies are Pydantic models; invalid input returns a 422 error with details.",
   "Dependencies (Depends) inject shared things such as database sessions or the current user.",
   "async def routes let the server handle other requests while waiting for databases or AI APIs.",
   "Run with uvicorn (or the fastapi CLI); open /docs to test endpoints."],
  ["pip install \"fastapi[standard]\".",
   "Create main.py with the code below.",
   "Run fastapi dev main.py and open http://127.0.0.1:8000/docs.",
   "Create a lead with POST /leads and read it back with GET /leads/{id}.",
   "Add a POST /leads/{id}/summary route that calls an LLM.",
   "Write tests with FastAPI's TestClient and pytest."],
  "# pip install \"fastapi[standard]\" anthropic\nfrom fastapi import FastAPI, HTTPException\nfrom pydantic import BaseModel, EmailStr, Field\nimport anthropic\n\napp = FastAPI(title='Lead API')\nllm = anthropic.AsyncAnthropic()\nLEADS: dict[int, dict] = {}\n\nclass LeadIn(BaseModel):\n    name: str = Field(min_length=1)\n    email: EmailStr\n    message: str\n    budget_lakh: float | None = None\n\n@app.post('/leads', status_code=201)\nasync def create_lead(lead: LeadIn) -> dict:\n    lead_id = len(LEADS) + 1\n    LEADS[lead_id] = lead.model_dump()\n    return {'id': lead_id, **LEADS[lead_id]}\n\n@app.get('/leads/{lead_id}')\nasync def get_lead(lead_id: int) -> dict:\n    if lead_id not in LEADS:\n        raise HTTPException(status_code=404, detail='Lead not found')\n    return LEADS[lead_id]\n\n@app.post('/leads/{lead_id}/summary')\nasync def summarise(lead_id: int) -> dict:\n    lead = await get_lead(lead_id)\n    msg = await llm.messages.create(\n        model='claude-opus-5-5', max_tokens=500,\n        system='Summarise the enquiry in one sentence and suggest the next action.',\n        messages=[{'role': 'user', 'content': lead['message']}])\n    return {'summary': ''.join(b.text for b in msg.content if b.type == 'text')}\n\n# Run: fastapi dev main.py   then open http://127.0.0.1:8000/docs",
  ["Blocking calls (requests, time.sleep) inside async routes; use async clients.",
   "No input validation, or returning internal error details to users.",
   "Secrets in code instead of environment variables.",
   "No tests for the main routes."],
  [("Why FastAPI for AI services?", "Python ecosystem for AI, automatic validation with Pydantic, async support for slow I/O such as model calls, automatic OpenAPI docs, and high performance."),
   ("What does Depends do?", "It declares a dependency that FastAPI resolves for each request, such as a database session or the authenticated user, keeping routes small and testable."),
   ("How would you handle a slow LLM call?", "Use an async client with timeouts, stream the response if the user waits, or move long work to a background job and return a job ID the client can poll.")],
  "Build a FastAPI service with endpoints to upload a document, ask a question about it, and list past questions, with tests.",
  [("FastAPI: first steps (official)", "https://fastapi.tiangolo.com/tutorial/first-steps/"), ("FastAPI tutorial (official)", "https://fastapi.tiangolo.com/tutorial/"), ("Pydantic docs", "https://docs.pydantic.dev/latest/")]),

T("React",
  "React is a JavaScript library for building user interfaces from components: reusable functions that return markup (JSX) and update automatically when their data (state) changes. It is the most widely used front-end library and the base of Next.js and of most AI app builders' output.",
  "Customers see the AI through an interface: chat windows, dashboards, review queues and forms. FDEs build or adjust these UIs, and code from Lovable, v0 and similar tools is React.",
  ["Components: function ChatBox() { return <div>…</div> }.",
   "Props pass data from parent to child; state (useState) holds data a component owns.",
   "Changing state re-renders the component with new data.",
   "Effects (useEffect) run side effects such as loading data after render.",
   "Events: onClick, onChange, onSubmit handlers update state.",
   "Lists render with .map and need a stable key; conditional rendering shows loading and error states."],
  ["Create a project: npm create vite@latest ai-chat -- --template react-ts.",
   "npm install and npm run dev; open the local URL.",
   "Replace App.tsx with the chat component below.",
   "Point it at your FastAPI endpoint (enable CORS on the backend).",
   "Add loading, error and empty states.",
   "Build for production with npm run build."],
  "// src/App.tsx\nimport { useState } from 'react';\n\ntype Msg = { role: 'user' | 'assistant'; text: string };\n\nexport default function App() {\n  const [messages, setMessages] = useState<Msg[]>([]);\n  const [input, setInput] = useState('');\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState('');\n\n  async function send(e: React.FormEvent) {\n    e.preventDefault();\n    if (!input.trim()) return;\n    const next = [...messages, { role: 'user' as const, text: input }];\n    setMessages(next); setInput(''); setLoading(true); setError('');\n    try {\n      const res = await fetch('http://localhost:8000/chat', {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ question: input }),\n      });\n      if (!res.ok) throw new Error(`Server error ${res.status}`);\n      const data: { answer: string } = await res.json();\n      setMessages([...next, { role: 'assistant', text: data.answer }]);\n    } catch (err) {\n      setError((err as Error).message);\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  return (\n    <main style={{ maxWidth: 640, margin: '0 auto', padding: 16 }}>\n      <h1>Property assistant</h1>\n      {messages.length === 0 && <p>Ask about listings, prices or site visits.</p>}\n      {messages.map((m, i) => <p key={i}><b>{m.role === 'user' ? 'You' : 'Assistant'}:</b> {m.text}</p>)}\n      {loading && <p>Thinking…</p>}\n      {error && <p role=\"alert\">Could not get an answer: {error}</p>}\n      <form onSubmit={send}>\n        <input value={input} onChange={e => setInput(e.target.value)} placeholder=\"Type your question\" />\n        <button disabled={loading}>Send</button>\n      </form>\n    </main>\n  );\n}",
  ["Mutating state directly instead of creating new arrays/objects.",
   "Missing keys in lists.",
   "Calling AI APIs with secret keys from the browser.",
   "No loading or error states."],
  [("What is state and why is it immutable?", "State is data owned by a component that triggers re-renders when it changes. You replace it with new values (not mutate) so React can detect changes reliably."),
   ("How should a React app call an LLM?", "Through your own backend endpoint, which holds the API key, enforces auth and limits, and can stream the answer back.")],
  "Build a React review queue that lists AI-drafted emails from your API, lets a user edit, approve or reject each, and shows status updates.",
  [("React: learn (official)", "https://react.dev/learn"), ("Vite: getting started", "https://vite.dev/guide/"), ("TypeScript handbook", "https://www.typescriptlang.org/docs/handbook/intro.html")]),

T("Frontend and backend",
  "The frontend is the client-side interface users interact with (browser or app). The backend is the server-side system that holds business logic, data, secrets and integrations. They communicate through an API contract, usually REST with JSON over HTTPS.",
  "A clean split keeps secrets and rules on the server, lets several clients (web, mobile, partners) share one backend, and lets teams work in parallel. Many security problems in AI apps come from putting backend responsibilities in the frontend.",
  ["Frontend: renders UI, collects input, does light validation for usability, calls APIs, shows results.",
   "Backend: authenticates users, enforces permissions, validates all input again, talks to databases and AI providers, logs and monitors.",
   "API contract: endpoints, request and response shapes, error format; documented with OpenAPI.",
   "CORS: the browser only allows a page to call another origin if the backend permits that origin.",
   "Environments: local, staging and production each have their own URLs and keys.",
   "Streaming (server-sent events) lets the backend send AI tokens to the UI as they are generated."],
  ["Write the API contract first (endpoints, JSON shapes, errors).",
   "Build the backend endpoints with FastAPI and test them in /docs.",
   "Enable CORS for the frontend's origin only.",
   "Build the frontend against the contract.",
   "Move all secrets to the backend's environment variables.",
   "Deploy both and set the frontend's API base URL per environment."],
  "# Backend: allow only the frontend origin (FastAPI)\nfrom fastapi.middleware.cors import CORSMiddleware\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=['http://localhost:5173', 'https://app.example.com'],\n    allow_methods=['GET', 'POST'],\n    allow_headers=['Authorization', 'Content-Type'],\n)\n\n# Consistent error shape for every endpoint\nfrom fastapi.responses import JSONResponse\n@app.exception_handler(Exception)\nasync def unhandled(request, exc):\n    # log exc with a request id here; never return internal details\n    return JSONResponse(status_code=500, content={'error': 'internal_error', 'message': 'Something went wrong'})\n\n// Frontend: one API helper with the base URL from environment config\n// const API = import.meta.env.VITE_API_URL;\n// export async function api(path: string, body?: unknown) {\n//   const res = await fetch(`${API}${path}`, { method: body ? 'POST' : 'GET',\n//     headers: { 'Content-Type': 'application/json' }, body: body ? JSON.stringify(body) : undefined });\n//   if (!res.ok) throw new Error((await res.json()).message);\n//   return res.json();\n// }",
  ["Trusting frontend validation alone.",
   "allow_origins=['*'] with credentials in production.",
   "Leaking stack traces in API errors.",
   "Hard-coding production URLs in frontend code."],
  [("Why validate on both frontend and backend?", "Frontend validation improves the user experience; backend validation is the real protection because any client (or attacker) can call the API directly."),
   ("What is CORS?", "A browser security mechanism that blocks a page from reading responses from another origin unless that server explicitly allows the page's origin.")],
  "Write an OpenAPI contract for a document Q&A app, then build matching FastAPI and React parts and test them end to end.",
  [("MDN: CORS", "https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS"), ("FastAPI: CORS", "https://fastapi.tiangolo.com/tutorial/cors/"), ("OpenAPI specification", "https://spec.openapis.org/oas/latest.html")]),

T("Database integration",
  "Database integration connects your application code to a database to create, read, update and delete records safely and efficiently, usually through a driver plus an ORM (SQLAlchemy, SQLModel, Prisma) and a migration tool.",
  "Every real AI application stores users, conversations, documents, results, feedback and audit logs. Correct integration (schemas, migrations, transactions, connection pooling, parameterised queries) prevents data loss, leaks and slowdowns.",
  ["A driver (psycopg for PostgreSQL) sends SQL over a connection.",
   "An ORM maps tables to Python classes and builds safe, parameterised SQL.",
   "Sessions group operations into transactions (commit or rollback).",
   "Connection pools reuse connections instead of opening one per request.",
   "Migrations (Alembic) version schema changes so every environment matches.",
   "Indexes and query design keep reads fast as data grows."],
  ["Run PostgreSQL locally (Docker) or create a Supabase project.",
   "pip install sqlmodel psycopg[binary].",
   "Define models and create tables.",
   "Add a FastAPI dependency that provides a session per request.",
   "Write create and list endpoints.",
   "Add Alembic for migrations before the first production release."],
  "# pip install sqlmodel \"psycopg[binary]\" \"fastapi[standard]\"\nimport os\nfrom fastapi import FastAPI, Depends\nfrom sqlmodel import SQLModel, Field, Session, create_engine, select\n\nengine = create_engine(os.environ['DATABASE_URL'], pool_pre_ping=True)  # postgresql+psycopg://user:pass@host/db\n\nclass Lead(SQLModel, table=True):\n    id: int | None = Field(default=None, primary_key=True)\n    org_id: int = Field(index=True)          # tenant isolation\n    name: str\n    email: str = Field(index=True)\n    status: str = 'new'\n\nSQLModel.metadata.create_all(engine)       # use Alembic migrations in production\napp = FastAPI()\n\ndef get_session():\n    with Session(engine) as session:\n        yield session\n\n@app.post('/orgs/{org_id}/leads')\ndef create(org_id: int, lead: Lead, s: Session = Depends(get_session)) -> Lead:\n    lead.org_id = org_id\n    s.add(lead); s.commit(); s.refresh(lead)\n    return lead\n\n@app.get('/orgs/{org_id}/leads')\ndef list_leads(org_id: int, s: Session = Depends(get_session)) -> list[Lead]:\n    return list(s.exec(select(Lead).where(Lead.org_id == org_id).limit(100)))",
  ["Building SQL with f-strings and user input.",
   "Opening a new connection per query without pooling.",
   "Changing production schemas by hand without migrations.",
   "Forgetting the tenant filter on queries."],
  [("What is an ORM and its trade-offs?", "It maps database tables to code objects, giving safer queries and less boilerplate, but can hide inefficient SQL; inspect generated queries and drop to SQL when needed."),
   ("Why use migrations?", "They record every schema change as versioned code so all environments are reproducible, changes can be reviewed and rolled back, and deployments are automated."),
   ("What is the N+1 query problem?", "Loading a list then running one extra query per item; fix it with joins or eager loading.")],
  "Add a PostgreSQL database to your lead API with migrations, indexes, and a conversations table that stores every AI answer and user rating.",
  [("SQLModel docs", "https://sqlmodel.tiangolo.com/"), ("SQLAlchemy docs", "https://docs.sqlalchemy.org/"), ("Alembic tutorial", "https://alembic.sqlalchemy.org/en/latest/tutorial.html"), ("Supabase database docs", "https://supabase.com/docs/guides/database/overview")]),

T("Authentication",
  "Authentication verifies who a user or system is: passwords, magic links, social or enterprise single sign-on (Google, Microsoft Entra ID, Okta), multi-factor authentication, and API keys or tokens for machines.",
  "AI apps handle customer data and cost money per call. Without solid authentication anyone can read data or run up bills. Enterprise customers also require SSO and MFA before approving a deployment.",
  ["The user proves identity to an identity provider (your auth service, Supabase Auth, Auth0, Entra ID, Okta).",
   "On success the app receives a session or a signed token (JWT) with the user ID, expiry and claims.",
   "Each API request carries the token (Authorization: Bearer …) or a secure, HttpOnly session cookie.",
   "The backend verifies the signature and expiry before doing anything.",
   "OAuth 2.0 and OpenID Connect are the standards behind 'Sign in with Google/Microsoft' and enterprise SSO.",
   "Passwords are never stored in plain text; providers hash them with slow algorithms (bcrypt, Argon2)."],
  ["Use a managed provider instead of building auth yourself (Supabase Auth, Auth0, Clerk, Entra ID).",
   "Add sign-up and login to the frontend with the provider's SDK.",
   "Send the access token to your backend with each request.",
   "In FastAPI, verify the token in a dependency and load the user.",
   "Protect every non-public route with that dependency.",
   "Turn on MFA and set short token lifetimes with refresh tokens."],
  "# Verify a Supabase (or other provider) JWT in FastAPI\n# pip install pyjwt \"fastapi[standard]\"\nimport os, jwt\nfrom fastapi import Depends, HTTPException\nfrom fastapi.security import HTTPBearer, HTTPAuthorizationCredentials\n\nbearer = HTTPBearer()\nSECRET = os.environ['JWT_SECRET']          # or verify with the provider's public keys (JWKS)\n\ndef current_user(creds: HTTPAuthorizationCredentials = Depends(bearer)) -> dict:\n    try:\n        claims = jwt.decode(creds.credentials, SECRET, algorithms=['HS256'], audience='authenticated')\n    except jwt.ExpiredSignatureError:\n        raise HTTPException(401, 'Session expired, please log in again')\n    except jwt.InvalidTokenError:\n        raise HTTPException(401, 'Invalid token')\n    return {'id': claims['sub'], 'email': claims.get('email'), 'role': claims.get('role')}\n\n@app.get('/me')\ndef me(user: dict = Depends(current_user)) -> dict:\n    return user",
  ["Building your own password storage and login from scratch.",
   "Storing tokens in localStorage where scripts can steal them, without considering cookies.",
   "Long-lived tokens with no revocation.",
   "Checking login in the frontend only."],
  [("Authentication vs authorisation?", "Authentication confirms identity (who you are); authorisation decides permissions (what you can do). Both run on every protected request."),
   ("What is a JWT and what are its risks?", "A signed token carrying claims such as user ID and expiry. Risks: it cannot easily be revoked before expiry, it must be verified properly (algorithm, signature, audience), and it must not carry secrets."),
   ("What is SSO and why do enterprises require it?", "Single sign-on lets employees use their company identity (via SAML or OpenID Connect) so IT controls access centrally, enforces MFA and removes access when people leave.")],
  "Add Supabase Auth to your React + FastAPI app: login, protected routes, and a /me endpoint that verifies the token.",
  [("OWASP Authentication Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"), ("Supabase Auth docs", "https://supabase.com/docs/guides/auth"), ("OAuth 2.0 simplified", "https://www.oauth.com/")]),

T("Authorisation",
  "Authorisation decides what an authenticated user or service is allowed to do and which data it may see: role-based access control (RBAC), attribute-based rules, resource ownership and tenant isolation, enforced in the backend and, ideally, in the database.",
  "Most data leaks in multi-user apps are authorisation bugs: user A reads user B's record by changing an ID. In AI apps this extends to retrieval: RAG must only return documents the user may read, and agents must only call tools the user is allowed to use.",
  ["Roles group permissions (owner, admin, agent, viewer).",
   "Every request checks the user's role and ownership of the resource (object-level authorisation).",
   "Tenant isolation: every query filters by the user's organisation.",
   "Row-level security (PostgreSQL/Supabase RLS) enforces rules inside the database as a second layer.",
   "AI-specific: filter retrieval by permission metadata; give agent tools the user's permissions, not admin rights.",
   "Log denied attempts for security monitoring."],
  ["List roles and the actions each may perform (a permission matrix).",
   "Add org_id and owner fields to every tenant table.",
   "Write a FastAPI dependency require_role('admin').",
   "Filter every query by org_id from the token, never from user input.",
   "Enable RLS policies in the database.",
   "Write tests that try to access another tenant's data and expect 403/404."],
  "from fastapi import Depends, HTTPException\n\nPERMISSIONS = {\n    'owner':  {'leads:read', 'leads:write', 'billing:manage', 'users:manage'},\n    'admin':  {'leads:read', 'leads:write', 'users:manage'},\n    'agent':  {'leads:read', 'leads:write'},\n    'viewer': {'leads:read'},\n}\n\ndef require(permission: str):\n    def check(user: dict = Depends(current_user)) -> dict:\n        if permission not in PERMISSIONS.get(user['role'], set()):\n            raise HTTPException(403, 'You do not have permission for this action')\n        return user\n    return check\n\n@app.delete('/leads/{lead_id}')\ndef delete_lead(lead_id: int, user: dict = Depends(require('leads:write')), s=Depends(get_session)):\n    lead = s.get(Lead, lead_id)\n    if not lead or lead.org_id != user['org_id']:   # object-level + tenant check\n        raise HTTPException(404, 'Lead not found')\n    s.delete(lead); s.commit()\n    return {'deleted': lead_id}\n\n-- Supabase / PostgreSQL row-level security as a second layer\n-- alter table leads enable row level security;\n-- create policy \"members read own org\" on leads for select\n--   using (org_id in (select org_id from memberships where user_id = auth.uid()));",
  ["Checking the role but not resource ownership (IDOR vulnerability).",
   "Taking org_id from the request body instead of the verified token.",
   "Agents using an all-powerful service account.",
   "RAG search without permission filters."],
  [("What is an IDOR vulnerability?", "Insecure direct object reference: the app trusts an ID from the user without checking ownership, so changing the ID exposes someone else's data. Fix with object-level checks and tenant filters."),
   ("How do you apply authorisation to RAG?", "Store access metadata (tenant, groups, document ACLs) with each chunk and filter retrieval by the requesting user's permissions before anything reaches the model."),
   ("RBAC vs ABAC?", "RBAC grants permissions by role; ABAC evaluates attributes of user, resource and context (department, region, time). Many systems combine them.")],
  "Add roles and tenant isolation to your SaaS API, enable RLS, and write automated tests proving users cannot read or modify another organisation's data.",
  [("OWASP Authorization Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html"), ("OWASP API Security Top 10", "https://owasp.org/API-Security/"), ("Supabase: row level security", "https://supabase.com/docs/guides/database/postgres/row-level-security")]),

T("SaaS fundamentals",
  "Software as a service (SaaS) is software delivered online by subscription. A SaaS product needs more than features: multi-tenancy, sign-up and onboarding, organisations and roles, plans and billing, usage limits, admin tools, analytics, support and reliability.",
  "Many FDE solutions become products, and AI agencies often grow into SaaS. Knowing the building blocks lets you design solutions that scale to many customers and earn recurring revenue.",
  ["Multi-tenancy: one deployment serves many organisations; data is isolated by org_id (shared tables + RLS), separate schemas, or separate databases for large customers.",
   "Accounts: users belong to organisations through memberships with roles; invitations add teammates.",
   "Billing: plans (free, pro, enterprise) via Stripe or Razorpay; webhooks update the subscription status in your database.",
   "Metering: count usage (AI calls, documents, seats) per organisation and enforce plan limits.",
   "Onboarding: guide new organisations to first value quickly (sample data, checklists).",
   "Operations: admin console, product analytics, support, status page, backups and SLAs. Metrics: MRR, churn, activation, net revenue retention."],
  ["Model the core tables: organisations, users, memberships, plans, subscriptions, usage_events.",
   "Add sign-up that creates an organisation and an owner membership.",
   "Integrate Stripe Checkout (or Razorpay) and handle subscription webhooks.",
   "Record usage per AI call and block calls above the plan limit.",
   "Build an admin page listing organisations, plans and usage.",
   "Track activation events (first document uploaded, first answer accepted)."],
  "-- Core SaaS tables (PostgreSQL)\ncreate table organisations (id uuid primary key default gen_random_uuid(), name text not null, plan text not null default 'free', created_at timestamptz default now());\ncreate table memberships (org_id uuid references organisations(id), user_id uuid not null, role text not null check (role in ('owner','admin','member','viewer')), primary key (org_id, user_id));\ncreate table usage_events (id bigserial primary key, org_id uuid references organisations(id), kind text not null, units int not null default 1, at timestamptz default now());\ncreate index on usage_events (org_id, at);\n\n# Enforce plan limits before an AI call (Python)\nLIMITS = {'free': 100, 'pro': 5000, 'enterprise': None}   # AI calls per month\n\ndef check_quota(s, org) -> None:\n    limit = LIMITS[org.plan]\n    if limit is None:\n        return\n    used = s.exec(text(\"select coalesce(sum(units),0) from usage_events where org_id=:o and kind='ai_call' and at >= date_trunc('month', now())\"), {'o': org.id}).one()[0]\n    if used >= limit:\n        raise HTTPException(402, f'Monthly limit of {limit} AI calls reached. Upgrade your plan to continue.')",
  ["Adding multi-tenancy late, after data is mixed.",
   "Trusting the frontend for plan status instead of billing webhooks.",
   "No usage metering, so AI costs exceed revenue.",
   "No admin tools, so support needs database access."],
  [("How do you price an AI SaaS product?", "Start from customer value and your cost per unit (tokens, compute); combine a subscription with included usage and overage or tiers; keep gross margin healthy and test pricing with real customers."),
   ("Single-tenant vs multi-tenant?", "Multi-tenant shares infrastructure for lower cost and easier updates but needs strict isolation; single-tenant gives each customer separate infrastructure for stronger isolation and customisation at higher cost, often for large enterprises."),
   ("Which SaaS metrics matter early?", "Activation rate, weekly active organisations, retention cohorts, churn, MRR and gross margin (including AI costs).")],
  "Turn your document Q&A app into a multi-tenant SaaS with organisations, roles, a free and a pro plan, Stripe test-mode billing and usage limits.",
  [("Stripe billing docs", "https://docs.stripe.com/billing"), ("Supabase docs", "https://supabase.com/docs"), ("Y Combinator Startup School", "https://www.startupschool.org/"), ("AWS: SaaS lens (multi-tenancy)", "https://docs.aws.amazon.com/wellarchitected/latest/saas-lens/saas-lens.html")]),
]
